class Solution:
    def checktree(self, preorder, inorder, postorder, N):
        # helper function to compute postorder from preorder and inorder
        def build(pre, ino):
            if not pre:
                return []

            root = pre[0]
            idx = ino.index(root)

            left_post = build(pre[1:idx+1], ino[:idx])
            right_post = build(pre[idx+1:], ino[idx+1:])

            return left_post + right_post + [root]

        generated_post = build(preorder, inorder)

        return generated_post == postorder
